    --primary-color: rgb(39, 57, 109);
    --primary-color-darker: rgb(39, 57, 150);
}

@media (min-width:768px) {
    .dropdown>.drodown-menu {
        visibility: hidden;
        opacity: 0;
        top:100;
        display: block;
        transition: all 0.1s ease-out
    }

    .drodown:hover>.drodown-menu{
        padding:10px 0;
        display: block;
        visibility: visible;
        transition: all 0.3s ease-in-out
    }

    .dropdown-item:hover>.drodown-menu{
        color:#fff;
        background-color: black;
    }

}

* {
    box-sizing: border-box;
    outline: 0;
}

.quadro-texto {
    max-width: 768px;
    margin: 50px auto;
    background-color:  #f5ece3;
    padding: 25px;
}

body {
    margin: 0;
    padding: 0;
    background: var(--primary-color);
    font-family: 'Open sans', sans-serif;
    font-size: 1.3em;
    line-height: 1.5em;
}

h1 {
  font-size: 2.5em; 
}

h2 {
  font-size: 1.875em; 
}

h3 {
  font-size: 1.406em; 
}

h4 {
  font-size: 1.054em; 
}



p {
  font-size: 1em; 
}

.container {
    max-width: 768px;
    margin: 50px auto;
    background: #fff;
    padding: 20px;
    border-radius: 5px;
}

form input,
form label,
form button {
    display: block;
    width: 100%;
    margin-bottom: 10px;
}

form input {
    font-size: 24px;
    height: 50px;
    padding: 0 20px;
}

form input:focus {
    outline: 1px solid var(--primary-color);
}

form button {
    border: none;
    background: var(--primary-color);
    color: #fff;
    font-size: 18px;
    font-weight: 700;
    height: 50px;
    cursor: pointer;
    margin-top: 30px;
}

form button:hover {
    background: var(--primary-color-darker);
}


.nav-link {
    font-weight: 350;
    color: rgb(255, 253, 253);

}

.navbar-toogler:focus {
    box-shadow: none;
}

.dropdown>.drodown-menu {
    background-color: #fff;
    border: none;
    border-radius: 0;
}

.lni-grid-alt {
    font: size 1.5re;


